  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "NGB 2904, a lipophilic amide with a fused-ring system, entered the brain quickly and showed high brain penetration after IV dosing, supporting CNS access for the query's amide/fused-ring scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "JJC 4-077, which contains a hydroxylated side chain, entered the brain quickly and showed high brain penetration, indicating that polar hydroxyl groups do not preclude meaningful CNS access in this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Netupitant, a large lipophilic amide with a biphenyl group, crossed the BBB and distributed to multiple brain regions, supporting the query's potential for CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "[18F]PB118 showed excellent brain uptake (7 %ID/cc) in mice despite a polar amide/hydroxamic acid, demonstrating that polar amide-containing molecules can penetrate well.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A diethylamide with a basic piperidine showed very low brain uptake in mice; the query lacks this basic piperidine, so this negative result is less transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "[18F]MPPF is a p-gp substrate with low brain uptake; the query's neutral amide scaffold is not expected to share the same efflux liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted pass: the query is a neutral, lipophilic amide with a fused-ring/biphenyl scaffold; multiple structurally related amides show high brain penetration, and the negative analogues rely on basic amines or p-gp liabilities not present in the query.",
  "evidence_gaps": [
    "No direct experimental measurement for the query; all evidence is from analogues with Morgan similarity below 0.23.",
    "The query's diethanolamide and fused-ring polarity are not exactly represented in the high-penetration analogues.",
    "Efflux transporter status and unbound brain/plasma ratio for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

